export type MessageKey = keyof typeof en;
export type Messages = Partial<Record<MessageKey, string>>;


const loadedMessages: Partial<Record<Language, Messages>> = {en};
const localeLoaders: Record<Exclude<Language, 'en'>, () => Promise<{default: Messages}>> = {
  it: () => import('./locales/it.json'),
  es: () => import('./locales/es.json'),
  fr: () => import('./locales/fr.json'),
  de: () => import('./locales/de.json'),
};

export function hasMessages(language: Language): boolean {
  return loadedMessages[language] !== undefined;
}

export function messagesFor(language: Language): Messages {
  return loadedMessages[language] ?? en;
}

export async function loadMessages(language: Language): Promise<Messages> {
  if (loadedMessages[language]) return loadedMessages[language]!;
  const messages=(await localeLoaders[language as Exclude<Language, 'en'>]()).default;
  loadedMessages[language]=messages;
  return messages;
}
